#!/usr/bin/env python3
"""Generate synchronized Days 253–266 curriculum from its canonical source."""
from __future__ import annotations
import json, os, tempfile
from datetime import date, timedelta
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'docs/reboot/continuation-253-266'; SRC=OUT/'plan-source.json'
NAMES={'project':'project_implementation_tests','ai':'ai_workflow_implementation_evaluation','cert':'certification_labs_questions','ai_study':'ai_concept_source_study','cert_study':'certification_domain_study','core_study':'core_systems_security_cloud_study','evidence':'evidence'}
QT={'Q08':'API gateway: safe error contract','Q14':'Booking: retry after a lost response','Q20':'Payments: reconcile timeout','Q16':'Messaging: ordering and replay'}
def write(path,content):
 path.parent.mkdir(parents=True,exist_ok=True)
 with tempfile.NamedTemporaryFile('w',encoding='utf-8',dir=path.parent,delete=False) as f: f.write(content); tmp=Path(f.name)
 try: os.replace(tmp,path)
 finally: tmp.unlink(missing_ok=True)
def generate():
 p=json.loads(SRC.read_text()); tasks=p['tasks']; assert [t['day'] for t in tasks]==list(range(253,267)) and len(tasks)==14
 totals={k:sum(t[k] for t in tasks) for k in ('project','ai','cert','ai_study','cert_study','core_study')}
 want={'project':600,'ai':900,'cert':110,'ai_study':210,'cert_study':150,'core_study':130}; assert totals==want,(totals,want)
 sm={s['key']:s for s in p['sources']}; days=[]; cards=[]; notes=[]; start=date.fromisoformat(p['start_date'])
 for i,t in enumerate(tasks):
  d=t['day']; activities=t['activities']; alloc={NAMES[k]:t[k] for k in ('project','ai','cert','ai_study','cert_study','core_study')}; alloc['evidence']=15
  assert sum(alloc.values())==165 and sum(t[k] for k in ('project','ai','cert'))==115 and sum(t[k] for k in ('ai_study','cert_study','core_study'))==35
  refs=[]
  for a in activities.values():
   for key in a['source_keys']:
    if key not in {r['key'] for r in refs}:
     headings=[]
     for act in activities.values():
      if key in act['source_keys']:
       headings.extend(h for h in act.get('source_sections',{}).get(key,sm[key]['sections'][:1]) if h not in headings)
     refs.append({**sm[key],'sections':headings})
  refmap={r['key']:r for r in refs}; actrows={}
  for k,a in activities.items():
   desc='; '.join(a['source_paths']+[f"{refmap[x]['title']} — {', '.join(a.get('source_sections',{}).get(x,refmap[x]['sections']))} ({refmap[x]['url']})" for x in a['source_keys']]) or 'No external source; use named task and evidence record.'
   actrows[k]={**a,'source':desc}
  if t['shared']=='question': shared={'minutes':45,'within_engineering_minutes':False,'mode':'system_design_question_session','question_id':t['question_id'],'question_title':QT[t['question_id']],'task':t['shared_task'],'source':'docs/reboot/interview/question-bank.md'}
  elif t['shared']=='cert': shared={'minutes':45,'within_engineering_minutes':False,'mode':'certification_retrieval_review','question_id':None,'question_title':None,'task':t['shared_task'],'source':f"{t['cert_source_title']} — {t['cert_source_section']}"}
  else: shared={'minutes':45,'within_engineering_minutes':False,'mode':'unfinished_review','question_id':None,'question_title':None,'task':t['shared_task'],'source':'actual repository evidence and current next selector'}
  if shared['mode']=='system_design_question_session': shared['allocation_minutes']={'requirements':5,'constraints':5,'architecture_or_review':15,'failure_modes':10,'tradeoffs_and_next_step':10}
  arch=('Assistant-supplied design: a local adapter returns an already-verified typed assertion fixture; its verification flag must be the literal boolean True, never a truthy string or number. A deterministic policy boundary checks issuer, audience, validity, assertion/request/document tenant, group, scope, exact document ID/revision and active status before any bytes are disclosed. Denials use fixed reason codes and never echo claims or document text. The adapter flag is a test fixture, not cryptographic verification; no actual SAML parser, identity provider, AWS account, external write or model action exists. This is the single selected synthetic enterprise-contract branch. The learner implements and tests these supplied decisions; no capstone design proposal or post-hoc justification is assigned.')
  dt=(start+timedelta(days=i)).isoformat(); gate='python3 scripts/check_continuation_253_entry_gate.py'
  row={'day':d,'date':dt,'title':t['title'],'learner_seam':t['seam'],'module':'single synthetic enterprise identity/document contract rehearsal','signature':', '.join(t['files']),'selectors':[gate,p['prior_window_closeout']['selector'],t['selector'],*t['recovery_selectors']],'depends_on_days':[d-1] if i else [],'recovery_day':t['shared']=='review','study_refs':[r['url'] for r in refs],'study_guidance':refs,'engineering_architecture':{'decision':arch,'note_ref':f'assistant-architecture-notes.md#day-{d}','mode':'assistant_supplied_capstone_architecture; learner_implements_and_tests','capstone_proposal_required':False,'system_design_scope':'separate_interview_question_bank_only'},'budget':{'engineering_minutes':165,'study':35,'practice_and_tests':115,'evidence':15,'shared_interview_or_remaining_reviews_minutes':45,'total':210,'workstream_minutes':alloc},'workstream_minutes':alloc,'task_minutes':actrows,'shared_interview_block':shared,'learner_status':'unobserved_not_implied_by_scaffold','task':t,'synthetic_context':p['synthetic_context'],'separate_learning_repository':p['separate_learning_repository']}
  days.append(row); cards.append({'day_number':d,'date':dt,'title':t['title'],'learner_seam':t['seam'],'signature':row['signature'],'selectors':row['selectors'],'prerequisite_days':row['depends_on_days'],'recovery_day':row['recovery_day'],'engineering':{'minutes':165,'allocation':alloc},'budget_minutes':{'engineering':165,'shared_interview_or_remaining_reviews':45,'total':210},'activities':actrows,'study_guidance':refs,'shared_interview_block':shared,'assistant_architecture_note':row['engineering_architecture'],'status':'unobserved_not_implied_by_scaffold','separate_learning_repository':p['separate_learning_repository']})
  notes.append(f'<a id="day-{d}"></a>\n## Day {d} — {t["title"]}\n\n**Architecture:** {arch}\n')
  lines=[f'<a id="day-{d}"></a>',f'# Day {d}: {t["title"]}','',f'Date: {dt}','','**Scope:** '+t['context'],'','**Assistant-supplied architecture — what and why:** '+arch,'','## Engineering workstreams','']
  for k in NAMES.values():
   a=actrows[k]; lines += [f"### {k.replace('_',' ').title()} — {a['minutes']} minutes",'',f"**Task:** {a['task']}",f"**Source:** {a['source']}",f"**Command:** {a['command']}",f"**Evidence:** {a['evidence']}",'']
  dsa='[dsa-prep repository]('+p['separate_learning_repository']['algorithm_practice']+')'
  closeout=p['prior_window_closeout']
  lines += ['## Shared block — 45 minutes (outside engineering)','','**'+shared['mode']+':** '+shared['task'],'**Source:** '+shared['source'],'','## Gate and boundaries','',f"Run `{gate}` before learner workflow selectors. It checks the existing Day 210/238 gate and the prior window's assigned Day 252 record at `{closeout['evidence_path']}`. If Day 210/238 is not eligible, follow the existing CoverStory recovery selectors. If those are eligible but the Day 252 record is absent or invalid, run its already-assigned selector `{closeout['selector']}` and record the actual result before starting Days 253–266. Do not infer status permanently from the current scaffold. The gate awards eligibility only; an instructor witness is separate and earns no learner completion. System-design practice is only the named interview-bank question; DSA stays in the separate {dsa}. AWS sources are comparison-only; recheck current guide/version during study. Passing a test is neither a certification pass nor professional ownership evidence.",'', '**Learner status:** unobserved_not_implied_by_scaffold','']
  write(OUT/f'contracts/day-{d}.md','\n'.join(lines))
 allocation={NAMES[k]:v for k,v in want.items()}; allocation['evidence']=210
 manifest={'title':p['title'],'status':p['status'],'branch':p['branch'],'base_commit':p['base_commit'],'engineering_minutes':165,'engineering_allocation':allocation,'engineering_minutes_total':2310,'shared_interview_or_remaining_reviews_minutes':45,'total_daily_minutes':210,'scope':p['scope'],'gate_policy':p['gate'],'source_keys':[s['key'] for s in p['sources']],'days':days,'shared_allocation':p['shared_allocation'],'synthetic_context':p['synthetic_context'],'separate_learning_repository':p['separate_learning_repository']}
 transfer={'title':p['title'],'status':p['status'],'branch':p['branch'],'source':{'base_commit':p['base_commit'],'runtime':'Python standard library; offline synthetic fixture only'},'dates':{'start':p['start_date'],'end':p['end_date'],'recovery_days':[x['day'] for x in days if x['recovery_day']]},'budget':{'engineering_minutes':165,'allocation':{'study':35,'practice_and_tests':115,'evidence':15},'shared_interview_or_remaining_reviews_minutes':45,'total':210,'window_workstreams':allocation},'gate_policy':p['gate'],'recovery_selectors':p['recovery_selectors'],'days':days}
 owner={'title':p['title'],'status':p['status'],'branch':p['branch'],'base_commit':p['base_commit'],'board_writes':False,'story_count':14,'cards':cards,'shared_allocation':p['shared_allocation'],'separate_learning_repository':p['separate_learning_repository']}
 for name,obj in [('manifest.json',manifest),('days-253-266-transfer-plan.json',transfer),('scrum-owner-manifest.json',owner),('verified-sources.json',{'verified_at':'2026-10-24','recheck_before_study':True,'scope':'Exact source titles and headings verified on 2026-10-24; recheck in July 2027. Certification guides are current references only, not readiness claims. No AWS service, credential, API or paid exam use.','sources':p['sources']})]: write(OUT/name,json.dumps(obj,indent=2,ensure_ascii=False)+'\n')
 write(OUT/'assistant-architecture-notes.md','# Assistant-supplied architecture notes\n\nThe assistant selects one local synthetic identity/document contract behind a trusted adapter boundary and explains it. No actual federation, SAML parser, cloud service or live customer integration. The learner implements/tests; system design is practiced only in the separate interview bank.\n\n'+'\n'.join(notes))
 write(OUT/'README.md',f"# Days 253–266: synthetic enterprise identity/document contract\n\nStatus: bounded starter for review; dates 3–16 July 2027. This selects Branch A only from the reviewed fifth-window proposal. It rehearses one synthetic document and already-verified adapter assertion; no actual SAML parsing, IdP, AWS account, credential, provider, network, live data, external mutation or StreamForge work.\n\nRun `{gate}` before learner workflow selectors. If not eligible, use the first unmet CoverStory recovery selector for project time. Eligibility is not completion. Learner evidence remains unobserved until earned.\n\nThe engineering total is 2,310 minutes, 165 daily plus one shared 45-minute block. Project work is 600 minutes; AI evaluation 900; certification questions 110; AI study 210; certification-domain study 150; core study 130; evidence 210.\n\nThe official AWS SAA-C03 and Developer Associate guides were checked on 24 October 2026; Developer guide currently identifies DVA-C02. Recheck both guides and exact domain headings in July 2027. Study is limited and does not establish readiness or guarantee a pass. SDE II and Senior are knowledge/application checkpoints; Staff/Principal/FDE require separate real workplace evidence such as production ownership, incident responsibility, customer outcomes, cross-team impact or mentorship. Local portfolio work does not establish AWS deployment, professional customer ownership, or organizational impact.\n\nGenerate synchronized contracts and exports with `python3 scripts/generate_continuation_253_266.py`; validate with `python3 -m unittest scripts.test_continuation_253_266`. Instructor-only reference witnesses do not count as learner implementation or completion.\n")
 return manifest
if __name__=='__main__':
 m=generate(); print(f"generated {len(m['days'])} days; engineering={m['engineering_minutes_total']} min")
